/* Cybersecurity — L5 Architettura e avanzato: 6 lezioni approfondite (gestione, rischio, conformità, test autorizzati, architettura, continuità). */
(function (ST) {
  'use strict';
  const C = ST.content, { mc, fill, order } = C;

  /* ---------- 1 · Vulnerabilità e CVSS ---------- */
  C.addTopic({
    id: 'cyb-gestione-vulnerabilita-e-cvss', subject: 'cyb', stage: 'L5', minutes: 14,
    title: 'Gestione delle vulnerabilità e CVSS',
    summary: 'Il ciclo di vita delle vulnerabilità, CVE, CWE e CVSS v3.1 con un calcolo completo, e come dare le priorità oltre il solo punteggio.',
    objectives: ['Descrivere il ciclo di gestione delle vulnerabilità e distinguere CVE, CWE e CVSS', 'Leggere un vettore CVSS v3.1 e calcolarne il punteggio base', 'Dare priorità ai rimedi usando contesto, sfruttabilità e criticità dell’asset'],
    pages: [
      { h: 'Il ciclo di vita', b: `Una **vulnerabilità** è una debolezza che può essere sfruttata per violare riservatezza, integrità o disponibilità. Gestirle non è «installare patch ogni tanto»: è un **processo continuo**.\n\n1. **Inventario**: non puoi proteggere ciò che non sai di avere.\n2. **Individuazione**: scansioni autorizzate, avvisi dei fornitori, segnalazioni.\n3. **Valutazione**: la vulnerabilità riguarda davvero noi? Quanto è grave *qui*?\n4. **Priorità**: cosa si corregge per primo.\n5. **Rimedio**: patch, aggiornamento, configurazione, controllo compensativo.\n6. **Verifica**: una nuova scansione conferma che il problema è chiuso.\n7. **Reporting e miglioramento**: tempi, ritardi, cause ricorrenti.\n\n> Una scansione senza inventario produce elenchi enormi ma ciechi: non sai a chi appartiene la macchina né quanto vale.\n\nIl ciclo è un cerchio, non una retta: ogni nuovo asset e ogni nuovo avviso lo rimettono in moto.` },
      { h: 'CVE, CWE e CVSS: tre cose diverse', b: `Tre sigle che si confondono spesso.\n\n- **CVE** (Common Vulnerabilities and Exposures): un **identificatore** pubblico per una vulnerabilità specifica in un prodotto, nel formato CVE-anno-numero. Dice *quale* problema.\n- **CWE** (Common Weakness Enumeration): un catalogo di **tipi di debolezza** nel software (per esempio la validazione insufficiente dell’input). Dice *che genere* di errore.\n- **CVSS** (Common Vulnerability Scoring System): un sistema per esprimere la **gravità tecnica** con un punteggio da 0,0 a 10,0. Dice *quanto è seria* in astratto.\n\n> CVE = il caso concreto. CWE = la famiglia di errori. CVSS = il voto di gravità.\n\nI dati arrivano in archivi come la **NVD**, che raccoglie CVE con punteggi e riferimenti. Un CVE senza punteggio o senza patch non significa «innocuo»: significa solo che l’analisi non è ancora completa.\n\nDi regola l’**avviso del produttore** è la fonte più precisa su quali versioni sono colpite e su come correggere.` },
      { h: 'CVSS v3.1: le metriche base', b: `Il punteggio **base** descrive la vulnerabilità in sé, senza contesto, tramite otto metriche.\n\n**Sfruttabilità**\n- **AV** (Attack Vector): da dove si raggiunge: Network, Adjacent, Local, Physical.\n- **AC** (Attack Complexity): Low o High, cioè se servono condizioni particolari fuori dal controllo di chi attacca.\n- **PR** (Privileges Required): None, Low, High.\n- **UI** (User Interaction): None o Required (serve che una persona faccia qualcosa).\n\n**Ambito**\n- **S** (Scope): Unchanged o Changed, cioè se l’impatto esce dal componente vulnerabile verso altri.\n\n**Impatto**\n- **C**, **I**, **A**: riservatezza, integrità, disponibilità, ciascuna None, Low o High.\n\nUn vettore si scrive così:\n\n> AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H\n\nLetto: raggiungibile dalla rete, semplice, senza privilegi né interazione, ambito invariato, impatto alto su tutte e tre le proprietà.\n\n**Fasce di gravità**: 0,0 nessuna; 0,1–3,9 bassa; 4,0–6,9 media; 7,0–8,9 alta; 9,0–10,0 critica.` },
      { h: 'Calcolo svolto del punteggio base', b: `Con ambito **invariato** si usano i pesi ufficiali. Per AV:N = 0,85, AC:L = 0,77, PR:N = 0,85, UI:N = 0,85. Per C, I, A: High = 0,56, Low = 0,22, None = 0.\n\nCaso AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H.\n\n1. **ISS** = 1 − (1 − C)(1 − I)(1 − A) = 1 − 0,44 × 0,44 × 0,44 = 1 − 0,085184 = **0,914816**\n2. **Impatto** = 6,42 × ISS = 6,42 × 0,914816 ≈ **5,873**\n3. **Sfruttabilità** = 8,22 × 0,85 × 0,77 × 0,85 × 0,85 ≈ **3,887**\n4. Somma = 5,873 + 3,887 = 9,760\n5. **Base** = arrotondamento **per eccesso** al decimale (min con 10) = **9,8**\n\n> Arrotondare per eccesso significa che 9,76 diventa 9,8 (non 9,7): si sale sempre al primo decimale non inferiore al valore.\n\nSe l’ambito è **Changed** (S:C) cambiano la formula dell’impatto e il fattore finale 1,08, e un PR più alto pesa di più: la logica resta quella di sommare impatto e sfruttabilità.` },
      { h: 'Altri esempi e come leggerli', b: `Lo stesso procedimento dà esiti molto diversi.\n\n> **AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:N/A:N**: ISS = 0,56; Impatto = 6,42 × 0,56 = 3,595; con sfruttabilità 3,887 si ha 7,482, arrotondato **7,5** (alta). Perde solo la riservatezza, ma è raggiungibile e semplice.\n\n> **AV:N/AC:L/PR:N/UI:N/S:U/C:L/I:N/A:N**: ISS = 0,22; Impatto = 1,412; somma 5,299, arrotondata **5,3** (media).\n\n> **AV:L/AC:L/PR:L/UI:N/S:U/C:H/I:H/A:H**: sfruttabilità = 8,22 × 0,55 × 0,77 × 0,62 × 0,85 ≈ 1,835; con impatto 5,873 la somma è 7,708, cioè **7,8** (alta).\n\nOsserva: cambiare **da rete a locale** e richiedere privilegi bassi abbassa di molto la sfruttabilità, ma l’impatto massimo mantiene il punteggio alto.\n\nUn punteggio **non** misura il rischio per la tua organizzazione: misura quanto è grave la debolezza *in generale*. Per questo serve un secondo passo.` },
      { h: 'Priorità oltre il punteggio', b: `Se si correggesse tutto ciò che ha CVSS alto, si perderebbe tempo su problemi irrilevanti e se ne ignorerebbero altri. Il contesto conta.\n\n- **Sfruttabilità reale**: esiste codice dimostrativo pubblico? Si osservano attacchi in corso?\n- **EPSS** (Exploit Prediction Scoring System): stima la **probabilità** che una vulnerabilità venga sfruttata nei prossimi 30 giorni, basandosi sui dati osservati. Non sostituisce CVSS: lo affianca (gravità contro probabilità).\n- **Catalogo KEV** (Known Exploited Vulnerabilities) della CISA: elenco di vulnerabilità **sfruttate attivamente**. Essere presenti lì è un forte segnale di urgenza.\n- **Criticità dell’asset**: un 7,5 sul server dei pagamenti vale più di un 9,0 su un laboratorio isolato e senza dati.\n- **Esposizione**: raggiungibile da Internet o solo dalla rete interna?\n- **Controlli esistenti**: segmentazione, WAF o altre misure possono ridurre il rischio mentre si prepara la patch.\n\n> Una regola pratica: *esposto + sfruttato attivamente + asset critico* sale in cima alla lista, qualunque sia il numero CVSS.` },
      { h: 'SLA, eccezioni e accettazione del rischio', b: `Per rendere il processo prevedibile si fissano **SLA** (tempi massimi di rimedio) in una politica approvata dal management.\n\n> Esempio: critica entro 7 giorni; alta entro 30; media entro 90; bassa al ciclo di manutenzione successivo. Per vulnerabilità sfruttate attivamente su sistemi esposti, tempi anche più brevi.\n\nNon sempre si può applicare una patch: il sistema è fuori supporto, un aggiornamento rompe un’applicazione, il fermo costa troppo. Allora si usa una **eccezione formale**:\n\n- motivo documentato;\n- **controlli compensativi** (isolamento, monitoraggio, riduzione dei privilegi);\n- **responsabile** che accetta il rischio, di livello adeguato;\n- **scadenza** e data di riesame.\n\nL’**accettazione del rischio** è una decisione legittima, ma deve essere **consapevole, documentata e a tempo**. Un’eccezione senza scadenza è un rischio dimenticato.\n\nMisure utili: tempo medio di rimedio, percentuale entro SLA, età delle vulnerabilità aperte, numero di eccezioni scadute.` }
    ],
    exercises: [
      mc('Quale sigla identifica una specifica vulnerabilità in un prodotto?', ['CVE', 'CWE', 'CVSS', 'EPSS'], 0, 'CVE è l’identificatore pubblico del caso concreto; CWE è il tipo di debolezza; CVSS è il punteggio di gravità.'),
      mc('Che cosa descrive la metrica CVSS «AV»?', ['Da dove è raggiungibile la vulnerabilità', 'Quanti privilegi servono', 'Se serve un’azione dell’utente', 'L’impatto sulla disponibilità'], 0, 'AV è l’Attack Vector: rete, adiacente, locale o fisico.'),
      fill('Con C:H, I:H, A:H e pesi High = 0,56, calcola ISS = 1 − 0,44 × 0,44 × 0,44. Quanto vale (tre decimali)?', ['0,915', '0.915', '0,914816', '0.914816'], 'Il prodotto è 0,085184; 1 − 0,085184 = 0,914816 ≈ 0,915.'),
      fill('Per AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H il punteggio base arrotondato è…', ['9,8', '9.8'], 'Impatto 5,873 + sfruttabilità 3,887 = 9,760, arrotondato per eccesso a 9,8.'),
      fill('Con solo C:H (I e A None) e ISS = 0,56, quanto è l’impatto 6,42 × ISS? (due decimali)', ['3,60', '3.60', '3,6', '3.6'], '6,42 × 0,56 = 3,5952, cioè circa 3,60.'),
      mc('AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:N: ISS = 0,8064, impatto 5,177, sfruttabilità 3,887. Il punteggio base è:', ['9,1', '9,0', '8,9', '9,8'], 0, 'Somma 9,064 arrotondata per eccesso a 9,1 (fascia critica).'),
      mc('Perché il punteggio CVSS base non basta per decidere le priorità?', ['Non tiene conto di contesto, esposizione e valore degli asset', 'Perché è sempre sbagliato', 'Perché vale solo per i sistemi Windows', 'Perché CVSS misura la probabilità di attacco'], 0, 'CVSS base misura la gravità tecnica in astratto; il rischio reale dipende dal contesto.'),
      mc('Qual è l’idea alla base di EPSS?', ['Stimare la probabilità che una vulnerabilità sia sfruttata a breve', 'Contare i CVE di un fornitore', 'Sostituire la scansione', 'Misurare il costo di una patch'], 0, 'EPSS fornisce una probabilità di sfruttamento, da affiancare alla gravità.'),
      mc('Che cosa segnala la presenza di una vulnerabilità in un catalogo KEV?', ['Che è stata sfruttata attivamente e va trattata con urgenza', 'Che non ha patch', 'Che è solo teorica', 'Che riguarda solo software libero'], 0, 'KEV elenca vulnerabilità con sfruttamento osservato.'),
      mc('Un’eccezione di patch ben fatta deve avere:', ['Controlli compensativi, responsabile e scadenza', 'Solo l’approvazione del tecnico', 'Nessuna scadenza', 'Nessuna documentazione per velocità'], 0, 'L’accettazione del rischio è legittima se consapevole, documentata e a tempo.'),
      order('Ordina il ciclo di gestione delle vulnerabilità', ['Inventario', 'Individuazione', 'Valutazione', 'Priorità', 'Rimedio', 'Verifica'], 'Prima sai cosa hai, poi trovi, valuti, ordini, correggi e verifichi.')
    ],
    test: [
      mc('CWE indica:', ['Un tipo di debolezza software', 'Un singolo avviso di un prodotto', 'Un punteggio di gravità', 'Un catalogo di exploit'], 0, 'CWE classifica le famiglie di debolezze.'),
      mc('In CVSS, S:C (Scope Changed) significa che:', ['L’impatto può estendersi oltre il componente vulnerabile', 'L’attacco richiede un utente', 'La vulnerabilità è stata corretta', 'L’attacco è solo fisico'], 0, 'Changed indica un impatto su componenti con autorità di sicurezza diversa.'),
      fill('Quale fascia di gravità spetta a un punteggio 7,5 (bassa, media, alta, critica)?', ['alta'], '7,0–8,9 è la fascia alta.'),
      fill('Impatto = 6,42 × 0,22 per un solo C:L. Quanto fa, con due decimali?', ['1,41', '1.41'], '6,42 × 0,22 = 1,4124.'),
      mc('Con sfruttabilità 3,887 e impatto 1,412 la somma è 5,299. Il base è:', ['5,3', '5,2', '5,4', '5,0'], 0, 'Si arrotonda per eccesso al primo decimale: 5,3.'),
      mc('Quale caso va corretto per primo, a parità di altro?', ['Esposto a Internet, sfruttato attivamente, asset critico', 'Solo locale, nessun exploit noto, laboratorio isolato dalla rete', 'Con punteggio basso ma su sistema non esposto a Internet', 'Su un server già dismesso e spento'], 0, 'Esposizione, sfruttamento reale e criticità dominano la priorità.'),
      mc('Se si correggono 180 vulnerabilità su 200 entro SLA, la percentuale entro SLA è:', ['90%', '80%', '95%', '18%'], 0, '180 : 200 = 0,9.')
    ]
  });

  /* ---------- 2 · Rischio quantitativo ---------- */
  C.addTopic({
    id: 'cyb-rischio-quantitativo', subject: 'cyb', stage: 'L5', minutes: 14,
    title: 'Rischio quantitativo: SLE, ARO e ALE',
    summary: 'Tradurre il rischio in numeri con valore dell’asset, SLE, ARO e ALE, valutare il rapporto costo-beneficio dei controlli e conoscere i limiti dei numeri.',
    objectives: ['Calcolare SLE, ARO e ALE con la formula ALE = SLE × ARO', 'Valutare il costo-beneficio di un controllo e il rischio residuo', 'Usare un registro dei rischi e riconoscere i limiti delle stime'],
    pages: [
      { h: 'Che cos’è il rischio', b: `Un **rischio** combina la **probabilità** che accada qualcosa di dannoso con il suo **impatto**. Si parte da tre elementi:\n\n- **asset**: ciò che ha valore (dati, sistemi, reputazione);\n- **minaccia**: ciò che può causare danno;\n- **vulnerabilità**: la debolezza che permette alla minaccia di agire.\n\nSenza uno dei tre non c’è rischio: una debolezza che nessuna minaccia può raggiungere, o un asset senza valore, pesano poco.\n\nCi sono due approcci:\n\n- **qualitativo**: scale come basso/medio/alto e matrici probabilità × impatto. Veloce, ma soggettivo.\n- **quantitativo**: valori in denaro e frequenze. Più oggettivo nella forma, ma richiede dati e stime.\n\n> Un rischio qualitativo dice «alto». Uno quantitativo dice «circa 32 000 € di perdita attesa all’anno»: confrontabile con il costo di una difesa.\n\nIn pratica si **combinano**: la matrice per ordinare molti rischi, i numeri per decidere sui più importanti.` },
      { h: 'Valore dell’asset ed Exposure Factor', b: `Il primo passo è stimare il **valore dell’asset** (AV). Non è solo il prezzo d’acquisto: include il costo di **sostituzione e ripristino**, l’**interruzione dell’attività**, i danni **contrattuali o di reputazione** e, dove pertinente, le sanzioni.\n\nL’**Exposure Factor** (EF) è la **percentuale del valore** che si perde in un singolo evento: va da 0% a 100%.\n\n> Un incendio nel locale server può distruggere il 100% dell’hardware. Un malware ripristinato da backup può costare solo il 10% del valore dei dati.\n\nDa questi due numeri nasce la **Single Loss Expectancy**:\n\n> **SLE = valore dell’asset × EF**\n\nEsempio: asset da 200 000 €, EF 25% → SLE = 200 000 × 0,25 = **50 000 €** per ogni evento.\n\nL’SLE risponde a: «Se succede una volta, quanto ci costa?». Non dice ancora *quanto spesso* succede.` },
      { h: 'ARO e ALE', b: `L’**Annualized Rate of Occurrence** (ARO) è il numero **atteso di eventi per anno**.\n\n- Un evento ogni anno: ARO = 1.\n- Uno ogni due anni: ARO = 0,5.\n- Uno ogni 10 anni: ARO = 0,1.\n- Quattro volte all’anno: ARO = 4.\n\nL’**Annualized Loss Expectancy** è la perdita media annua:\n\n> **ALE = SLE × ARO**\n\n**Esempio 1** (guasto serio al server): SLE 50 000 €, ARO 0,5 → ALE = **25 000 €** all’anno.\n\n**Esempio 2** (smarrimento di portatili): SLE 1 500 €, ARO 4 → ALE = **6 000 €** all’anno.\n\n**Esempio 3** (ransomware): asset 800 000 €, EF 40% → SLE 320 000 €; ARO 0,1 → ALE = **32 000 €** all’anno.\n\n> Attenzione: ALE è una **media**. Un evento da 320 000 € ogni 10 anni non significa spendere 32 000 € ogni anno: significa che, in media, è questo il peso annuo del rischio, utile per confrontare le alternative.\n\nL’ARO si stima da dati storici, statistiche di settore e giudizio degli esperti.` },
      { h: 'Costo-beneficio di un controllo', b: `Un controllo di sicurezza ha senso se **riduce il rischio più di quanto costa**. Si confrontano l’ALE prima e dopo.\n\n> **Beneficio annuo = ALE prima − ALE dopo**\n> **Valore netto = beneficio annuo − costo annuo del controllo**\n\nRiprendiamo il ransomware dell’esempio 3 (ALE 32 000 €). Introduciamo backup isolati e un sistema EDR (rilevamento sugli endpoint) per **12 000 €** all’anno. L’ARO scende da 0,1 a 0,04 e l’EF resta 40%:\n\n- ALE dopo = 320 000 × 0,04 = **12 800 €**\n- Beneficio = 32 000 − 12 800 = **19 200 €**\n- Valore netto = 19 200 − 12 000 = **+7 200 €** all’anno\n\nIl controllo conviene.\n\n**Controesempio**: un controllo da 50 000 € che riduce un ALE da 72 000 € a 30 000 € dà beneficio 42 000 €; netto = 42 000 − 50 000 = **−8 000 €**. Sul piano puramente economico non conviene (ma obblighi di legge o altri vincoli possono comunque imporlo).\n\nNel costo conta il **totale**: acquisto, installazione, formazione, gestione.` },
      { h: 'Rischio residuo e opzioni di trattamento', b: `Dopo i controlli rimane il **rischio residuo**: nel caso precedente, l’ALE di 12 800 € all’anno. Il rischio **inerente** è quello prima dei controlli (32 000 €).\n\nLe quattro opzioni di trattamento:\n\n- **Ridurre**: aggiungere controlli (backup, segmentazione, formazione).\n- **Trasferire**: assicurazione o contratti con terzi. Si trasferisce l’impatto economico, non la responsabilità verso clienti e autorità.\n- **Evitare**: eliminare l’attività o il sistema che crea il rischio.\n- **Accettare**: decidere consapevolmente di conviverci, quando il rischio residuo rientra nella **propensione al rischio** dell’organizzazione.\n\n> Il rischio residuo non è mai zero: l’obiettivo è portarlo a un livello **accettabile e approvato** da chi ne ha l’autorità.\n\nL’accettazione spetta al **responsabile del business**, non al solo reparto tecnico, e va registrata con data e motivazione.` },
      { h: 'Il registro dei rischi', b: `Il **registro dei rischi** (risk register) è il documento vivo in cui tutto si raccoglie. Ogni voce contiene tipicamente:\n\n- descrizione del rischio e asset coinvolto;\n- **proprietario** (responsabile);\n- probabilità e impatto, oppure ALE;\n- controlli esistenti;\n- rischio residuo e decisione di trattamento;\n- azioni pianificate con scadenze;\n- data dell’ultimo riesame.\n\nUna matrice semplice può usare scale da 1 a 5: **punteggio = probabilità × impatto**.\n\n> Probabilità 4 e impatto 5 → punteggio **20** su 25: rischio da trattare con priorità. Probabilità 2 e impatto 3 → **6**.\n\nIl registro serve soprattutto se è **aggiornato**: nuovi sistemi, incidenti avvenuti, cambi normativi e controlli realizzati lo modificano. Viene riesaminato a scadenze regolari e dopo ogni evento importante.\n\nÈ anche lo strumento con cui il management vede *che cosa* si è deciso di accettare e *chi* lo ha deciso.` },
      { h: 'FAIR e i limiti dei numeri', b: `**FAIR** (Factor Analysis of Information Risk) è un modello che scompone il rischio in fattori misurabili: la **frequenza** con cui un evento di perdita può verificarsi (a sua volta funzione della frequenza di contatto con la minaccia e della probabilità di successo) e l’**entità della perdita** (primaria e secondaria). Il risultato è espresso in valori monetari con **intervalli di confidenza**, non con un numero unico. A livello di concetto: ragionare per fattori e per intervalli.\n\nI **limiti** dei numeri vanno detti con onestà:\n\n- **dati storici scarsi** per eventi rari;\n- stime spesso **soggettive**, con falsa precisione (dare «32 000 €» come se fosse certo);\n- eventi **dipendenti** tra loro (un solo incidente può colpire più asset);\n- minacce che cambiano più in fretta dei dati;\n- danni **difficili da monetizzare** (fiducia, impatto sulle persone).\n\n> Meglio un intervallo motivato («tra 10 000 € e 60 000 € all’anno») di un numero esatto e infondato.\n\nI numeri non sostituiscono il giudizio: lo **informano** e rendono la discussione verificabile.` }
    ],
    exercises: [
      mc('Qual è la formula dell’ALE?', ['ALE = SLE × ARO', 'ALE = SLE + ARO', 'ALE = valore ÷ EF', 'ALE = ARO ÷ SLE'], 0, 'La perdita annua attesa è la perdita per evento moltiplicata per il numero atteso di eventi all’anno.'),
      fill('Asset da 120 000 € con EF 30%: quanto vale lo SLE in euro?', ['36000', '36 000', '36.000'], '120 000 × 0,30 = 36 000.'),
      fill('Un evento atteso ogni 4 anni: quanto vale l’ARO?', ['0,25', '0.25'], '1 ÷ 4 = 0,25.'),
      fill('SLE 36 000 € e ARO 2: quanto vale l’ALE in euro?', ['72000', '72 000', '72.000'], '36 000 × 2 = 72 000.'),
      fill('Esempio ransomware: asset 800 000 € e EF 40%. Quanto vale lo SLE in euro?', ['320000', '320 000', '320.000'], '800 000 × 0,40 = 320 000.'),
      fill('Con SLE 320 000 € e ARO 0,1, quanto vale l’ALE in euro?', ['32000', '32 000', '32.000'], '320 000 × 0,1 = 32 000.'),
      fill('ALE prima 32 000 €, dopo 12 800 €, costo del controllo 12 000 €. Qual è il valore netto annuo in euro?', ['7200', '7 200', '7.200'], 'Beneficio 19 200; netto 19 200 − 12 000 = 7 200.'),
      mc('Un controllo costa 50 000 € all’anno e riduce l’ALE da 72 000 € a 30 000 €. Che cosa conclude l’analisi economica?', ['Non conviene: valore netto −8 000 €', 'Conviene: valore netto +22 000 € l’anno', 'Conviene: valore netto +42 000 € l’anno', 'Pareggio esatto fra costo e beneficio'], 0, 'Beneficio 42 000 meno costo 50 000 = −8 000.'),
      mc('Che cos’è il rischio residuo?', ['Quello che resta dopo l’applicazione dei controlli', 'Quello prima di ogni controllo', 'Il costo dei controlli', 'Un rischio eliminato'], 0, 'Residuo = dopo i controlli; inerente = prima.'),
      mc('Con una matrice 1–5, probabilità 4 e impatto 5 danno punteggio:', ['20', '9', '25', '45'], 0, '4 × 5 = 20 su un massimo di 25.'),
      order('Ordina il calcolo dell’ALE', ['Valore asset', 'EF', 'SLE', 'ARO', 'ALE'], 'Dal valore e dall’EF si ottiene lo SLE; con l’ARO si ottiene l’ALE.')
    ],
    test: [
      mc('Che cosa rappresenta l’Exposure Factor?', ['La percentuale del valore persa in un singolo evento', 'Il numero di eventi per anno', 'Il costo di un controllo', 'La probabilità di attacco'], 0, 'EF va da 0% a 100% del valore dell’asset.'),
      fill('Asset da 500 000 €, EF 10%: quanto vale lo SLE in euro?', ['50000', '50 000', '50.000'], '500 000 × 0,10 = 50 000.'),
      fill('Con SLE 50 000 € e ARO 0,2, quanto vale l’ALE in euro?', ['10000', '10 000', '10.000'], '50 000 × 0,2 = 10 000.'),
      mc('SLE 1 500 € e ARO 4: l’ALE è:', ['6 000 €', '375 €', '1 504 €', '600 €'], 0, '1 500 × 4 = 6 000.'),
      mc('Quale opzione di trattamento è l’assicurazione?', ['Trasferire', 'Evitare', 'Accettare', 'Ridurre il valore'], 0, 'Si trasferisce l’impatto economico, non la responsabilità verso terzi.'),
      mc('Quale è un limite tipico della valutazione quantitativa?', ['Falsa precisione basata su stime incerte', 'Non usa mai numeri nelle stime', 'Funziona soltanto per i rischi fisici', 'Elimina del tutto il giudizio umano'], 0, 'Le stime di ARO ed EF sono spesso soggettive.'),
      mc('Perché è utile riportare un intervallo invece di un numero unico?', ['Perché comunica l’incertezza della stima', 'Perché è più facile da scrivere', 'Perché lo impone la legge', 'Perché elimina il rischio'], 0, 'L’approccio tipo FAIR usa intervalli per riflettere l’incertezza.')
    ]
  });

  /* ---------- 3 · Framework e conformità ---------- */
  C.addTopic({
    id: 'cyb-framework-e-conformita', subject: 'cyb', stage: 'L5', minutes: 14,
    title: 'Framework, standard e conformità',
    summary: 'ISO/IEC 27001 e 27002, NIST CSF, CIS Controls, SOC 2, nozioni di GDPR e NIS2 per chi lavora in sicurezza: a scopo didattico, non consulenza legale.',
    objectives: ['Distinguere standard, framework e normative e il loro scopo', 'Riconoscere le funzioni del NIST CSF e la struttura di ISO 27001/27002', 'Differenziare audit e assessment e capire i limiti della conformità'],
    pages: [
      { h: 'Avviso e panorama', b: `**Questa lezione è educativa e non costituisce consulenza legale.** Le norme cambiano e il loro effetto dipende da settore, dimensione e Paese: per decisioni reali ci si rivolge a un professionista qualificato e ai testi ufficiali.\n\nSi distinguono tre famiglie.\n\n- **Normative**: obbligatorie per legge (come il GDPR o la direttiva NIS2). Dicono *cosa* si deve ottenere, con sanzioni se non rispettate.\n- **Standard certificabili**: documenti tecnici, come ISO/IEC 27001, per cui un ente esterno può rilasciare una certificazione.\n- **Framework e linee guida**: raccolte di buone pratiche (NIST CSF, CIS Controls), usate volontariamente per strutturare e misurare il programma di sicurezza.\n\n> La normativa dice *devi proteggere i dati personali con misure adeguate*; lo standard e il framework aiutano a dimostrare *come*.\n\nL’obiettivo comune: gestire il rischio in modo **sistematico, documentato e verificabile**, non improvvisato.` },
      { h: 'ISO/IEC 27001 e 27002', b: `**ISO/IEC 27001** definisce i requisiti di un **Sistema di Gestione della Sicurezza delle Informazioni (ISMS)**. È uno standard **di gestione**: non elenca prodotti da comprare, ma impone un processo.\n\nIdee centrali:\n\n- **contesto e ambito**: che cosa è coperto dall’ISMS;\n- **leadership**: impegno e responsabilità della direzione, politica di sicurezza;\n- **valutazione e trattamento del rischio**, con una **Dichiarazione di Applicabilità** che elenca i controlli scelti e la motivazione;\n- **obiettivi misurabili**, audit interni, riesame della direzione;\n- **miglioramento continuo** (ciclo Plan-Do-Check-Act).\n\n**ISO/IEC 27002** è la guida ai **controlli**. Nell’edizione 2022 sono **93** controlli organizzati in 4 temi: organizzativi (37), delle persone (8), fisici (14), tecnologici (34).\n\n> 37 + 8 + 14 + 34 = 93.\n\nUn’organizzazione può essere **certificata 27001** da un ente accreditato dopo un audit; la 27002 non è oggetto di certificazione. La certificazione dice che il *sistema di gestione* esiste e funziona, non che nessun incidente accadrà.` },
      { h: 'NIST CSF e CIS Controls', b: `Il **NIST Cybersecurity Framework** (CSF) è un framework volontario per organizzare le attività di sicurezza. La versione 2.0 ha **sei funzioni**:\n\n- **Govern**: strategia, ruoli, politiche, supervisione del rischio;\n- **Identify**: conoscere asset, rischi e fornitori;\n- **Protect**: salvaguardie (accessi, formazione, protezione dei dati);\n- **Detect**: individuare eventi anomali;\n- **Respond**: contenere e gestire gli incidenti;\n- **Recover**: ripristinare e imparare.\n\nLa versione precedente (1.1) aveva cinque funzioni, senza Govern.\n\n**CIS Controls** (versione 8): **18 controlli** prioritizzati e concreti (inventario degli asset, configurazioni sicure, gestione degli accessi, backup...), con tre **gruppi di implementazione** (IG1, IG2, IG3) per adattarsi alla maturità e alle risorse.\n\n> Un’azienda piccola può partire da IG1 («igiene cibernetica di base») e crescere.\n\nIl CSF dice *che cosa* organizzare, i CIS Controls suggeriscono *da dove cominciare* in modo pratico.` },
      { h: 'SOC 2 e attestazioni', b: `**SOC 2** è un rapporto di **attestazione** emesso da un revisore indipendente (secondo i criteri dell’AICPA) sui controlli di un **fornitore di servizi**. È molto richiesto dai clienti che affidano dati a servizi cloud.\n\nSi basa sui **Trust Services Criteria**:\n\n- **sicurezza** (sempre inclusa);\n- **disponibilità**;\n- **integrità dell’elaborazione**;\n- **riservatezza**;\n- **privacy**.\n\nEsistono due tipi di rapporto:\n\n- **Type I**: i controlli sono **progettati** bene in una *data precisa*;\n- **Type II**: i controlli hanno anche **funzionato** in modo efficace in un *periodo* (per esempio sei mesi o un anno).\n\n> Il Type II è più affidabile perché guarda i controlli *nel tempo*, non in una fotografia.\n\nÈ un **rapporto**, non una certificazione in senso stretto, e non è obbligatorio per legge. Serve ai clienti come **prova** nella valutazione dei fornitori (vedi la lezione su continuità e terze parti).` },
      { h: 'GDPR: ciò che serve a chi fa sicurezza', b: `Il **GDPR** (Regolamento UE 2016/679) tutela i **dati personali** delle persone. Per chi si occupa di sicurezza, i punti fondamentali sono questi (in sintesi, non esaustivi).\n\n- Il trattamento richiede misure di sicurezza **adeguate al rischio** (art. 32): per esempio cifratura, riservatezza e resilienza dei sistemi, ripristino, verifiche periodiche.\n- **Privacy by design e by default**: la protezione dei dati si progetta fin dall’inizio.\n- **Violazione dei dati personali** (*data breach*): distruzione, perdita, modifica, divulgazione o accesso non autorizzati.\n- Il titolare deve **notificare** la violazione all’**autorità di controllo** senza ingiustificato ritardo e, **ove possibile, entro 72 ore** da quando ne è venuto a conoscenza, a meno che sia improbabile un rischio per le persone.\n- Se il rischio è **elevato** per le persone, vanno **informati** anche gli interessati.\n- Il responsabile del trattamento avvisa il titolare senza ingiustificato ritardo.\n\n> Per questo serve un processo di gestione degli incidenti già pronto: il tempo parte dalla *conoscenza* della violazione.\n\nLe sanzioni possono essere molto elevate; i dettagli per un caso reale vanno valutati con un esperto.` },
      { h: 'NIS2 a livello concettuale', b: `La **direttiva NIS2** (direttiva UE 2022/2555) mira a un **livello comune elevato di cibersicurezza** nell’Unione, ampliando i settori e i soggetti coinvolti rispetto alla precedente NIS.\n\nIdee di fondo, senza entrare nei dettagli dei singoli Paesi:\n\n- si rivolge a soggetti classificati come **essenziali** o **importanti** in settori ritenuti critici per la società;\n- richiede **misure di gestione del rischio** di cibersicurezza, anche sulla **catena di fornitura**;\n- prevede obblighi di **notifica degli incidenti significativi**, per fasi;\n- attribuisce **responsabilità alla direzione**, che deve approvare e supervisionare le misure;\n- prevede **vigilanza** da parte delle autorità e sanzioni.\n\n> Il messaggio per il lettore: la sicurezza è anche una **responsabilità di governo** dell’organizzazione, non solo del reparto IT.\n\nSe un’organizzazione rientri o no nell’ambito, e con quali obblighi, dipende dalla trasposizione nazionale e dal caso: va verificato con i testi ufficiali e con un consulente.` },
      { h: 'Audit, assessment e conformità reale', b: `Due attività simili ma diverse.\n\n- **Assessment** (valutazione): analisi del livello di sicurezza o di maturità rispetto a un riferimento, spesso interna e orientata al **miglioramento**. Produce raccomandazioni.\n- **Audit**: verifica **formale e indipendente**, con evidenze, rispetto a requisiti definiti (norma, politica, contratto). Esito: conformità, non conformità, osservazioni. Può essere **interno** (di prima parte), da **cliente** (seconda parte) o da **ente terzo** (terza parte, per la certificazione).\n\nUn audit raccoglie **evidenze**: documenti, registri, configurazioni, interviste, osservazioni.\n\n> «Se non è documentato, per l’auditor non esiste»: ma attenzione, i documenti devono corrispondere a ciò che si fa davvero.\n\n**Conformità non è sicurezza.** Si può essere conformi e vulnerabili (i requisiti sono un minimo, e fotografano un momento), o sicuri in pratica ma privi di prove. L’approccio sano: usare i framework come **struttura** e la valutazione del rischio per andare **oltre** il minimo richiesto.` }
    ],
    exercises: [
      mc('Qual è la differenza principale tra normativa e framework?', ['La normativa è obbligatoria, il framework è di norma volontario', 'Il framework prevede sanzioni di legge', 'La normativa è sempre tecnica', 'Non c’è differenza'], 0, 'Il GDPR è obbligatorio; il NIST CSF è una guida volontaria.'),
      mc('ISO/IEC 27001 è soprattutto:', ['Uno standard di gestione (ISMS) certificabile', 'Un elenco di prodotti', 'Una legge europea', 'Un test di intrusione'], 0, '27001 definisce i requisiti per un sistema di gestione della sicurezza.'),
      fill('Quanti controlli contiene ISO/IEC 27002 nell’edizione 2022?', ['93'], '37 + 8 + 14 + 34 = 93, in 4 temi.'),
      fill('Quanti sono i temi dei controlli di ISO/IEC 27002:2022?', ['4', 'quattro'], 'Organizzativi, persone, fisici, tecnologici.'),
      mc('Quale funzione è stata aggiunta nel NIST CSF 2.0?', ['Govern', 'Detect', 'Recover', 'Identify'], 0, 'La 1.1 aveva cinque funzioni; la 2.0 aggiunge Govern.'),
      fill('Quante funzioni ha il NIST CSF 2.0?', ['6', 'sei'], 'Govern, Identify, Protect, Detect, Respond, Recover.'),
      mc('I CIS Controls v8 sono:', ['18 controlli prioritizzati con gruppi IG1–IG3', '5 funzioni', '93 controlli', 'Una certificazione'], 0, 'Sono 18 controlli con tre gruppi di implementazione.'),
      mc('Un SOC 2 Type II attesta che i controlli:', ['Hanno funzionato in un periodo di tempo', 'Sono solo progettati in una certa data', 'Sono obbligatori per legge in ogni Paese', 'Eliminano ogni incidente di sicurezza'], 0, 'Il Type II valuta anche l’efficacia operativa nel periodo.'),
      mc('Entro quanto va notificata una violazione di dati personali all’autorità, ove possibile, secondo il GDPR?', ['72 ore dalla conoscenza', '24 ore dalla violazione', '7 giorni', '30 giorni'], 0, 'Senza ingiustificato ritardo e, ove possibile, entro 72 ore da quando se ne è venuti a conoscenza.'),
      mc('Quale affermazione su audit e conformità è corretta?', ['Essere conformi non garantisce di essere al sicuro', 'La certificazione elimina i rischi', 'Un audit non usa evidenze', 'Un assessment è sempre obbligatorio'], 0, 'Gli standard sono un minimo e fotografano un momento.'),
      order('Ordina le funzioni del NIST CSF 2.0 nell’ordine tipico di lettura', ['Govern', 'Identify', 'Protect', 'Detect', 'Respond', 'Recover'], 'Dal governo del rischio fino al ripristino.')
    ],
    test: [
      mc('Che cosa elenca la Dichiarazione di Applicabilità di ISO 27001?', ['I controlli scelti e la motivazione', 'Le sanzioni', 'Gli incidenti passati', 'I fornitori'], 0, 'Documenta quali controlli si applicano, quali no e perché.'),
      fill('Se i temi di ISO 27002:2022 contengono 37, 8, 14 e 34 controlli, quanti sono in totale?', ['93'], 'La somma è 93.'),
      mc('Quale tra queste NON è una funzione del NIST CSF 2.0?', ['Encrypt', 'Detect', 'Respond', 'Govern'], 0, 'Encrypt non è una funzione; le sei sono Govern, Identify, Protect, Detect, Respond, Recover.'),
      mc('Un audit di terza parte serve in genere a:', ['Ottenere una certificazione da ente indipendente', 'Fare un test di intrusione', 'Sostituire la gestione del rischio', 'Eliminare le non conformità'], 0, 'L’ente accreditato verifica la conformità ai requisiti.'),
      mc('Se il rischio per le persone è elevato, in caso di violazione il GDPR prevede di informare anche:', ['Gli interessati', 'Solo i fornitori', 'Solo i tecnici', 'Nessuno'], 0, 'Oltre all’autorità, vanno informati gli interessati.'),
      mc('NIS2 attribuisce responsabilità alla direzione perché:', ['La sicurezza è anche una responsabilità di governo', 'Solo il reparto IT conta', 'Non ha obblighi di gestione del rischio', 'È una norma tecnica sulla cifratura'], 0, 'Richiede approvazione e supervisione delle misure da parte degli organi di gestione.'),
      mc('Che cosa attesta una certificazione ISO 27001?', ['Che esiste e funziona un sistema di gestione, non che non ci saranno incidenti', 'Che l’organizzazione è immune dagli attacchi', 'Che tutti i sistemi sono privi di vulnerabilità', 'Che la legge è rispettata in ogni dettaglio'], 0, 'La certificazione riguarda il sistema di gestione, non l’assenza di incidenti.')
    ]
  });

  /* ---------- 4 · Test di penetrazione autorizzati ---------- */
  C.addTopic({
    id: 'cyb-test-di-penetrazione-autorizzati', subject: 'cyb', stage: 'L5', minutes: 14,
    title: 'Test di penetrazione autorizzati e pratica etica',
    summary: 'Ruoli red, blue e purple team, ambito e regole di ingaggio, fasi metodologiche a livello concettuale, report efficaci, bug bounty e ambienti legali per esercitarsi.',
    objectives: ['Distinguere red, blue e purple team e il ruolo dell’autorizzazione scritta', 'Descrivere le fasi di una metodologia e la struttura di un buon report', 'Indicare ambienti legali e sicuri per esercitarsi'],
    pages: [
      { h: 'Che cosa è (e che cosa non è)', b: `Un **test di penetrazione** (penetration test) è una verifica di sicurezza **autorizzata, concordata e limitata nel tempo**, in cui professionisti valutano se le difese di un sistema reggono, e riferiscono i risultati al proprietario perché possa correggere.\n\nIl confine con il reato è l’**autorizzazione**. Accedere a sistemi altrui senza permesso è illecito anche se l’intento è «per buon fine»: in Italia, per esempio, l’accesso abusivo a un sistema informatico è un reato previsto dal codice penale. Questa lezione è educativa e non è consulenza legale.\n\nCiò che distingue un test professionale:\n\n- **permesso scritto** dal titolare dei sistemi;\n- **ambito** e **regole** definite in anticipo;\n- **riservatezza** sui risultati;\n- obiettivo di **migliorare** la difesa, non di dimostrare abilità.\n\n> Un test non «dimostra che il sistema è sicuro»: mostra quali problemi sono stati trovati **nell’ambito e nel tempo concordati**.\n\nQuesta lezione parla di **metodo, responsabilità e comunicazione**, non di tecniche d’attacco.` },
      { h: 'Red, blue e purple team', b: `Nelle organizzazioni mature si distinguono ruoli diversi.\n\n- **Red team**: simula un avversario realistico per mettere alla prova **persone, processi e tecnologie** insieme, spesso con un obiettivo (per esempio «raggiungere un certo dato») e senza che tutta l’organizzazione ne sia informata.\n- **Blue team**: i **difensori**. Monitorano, rilevano, rispondono e rafforzano le difese.\n- **Purple team**: non è un gruppo fisso, ma un **modo di lavorare**: red e blue collaborano in modo trasparente, e ogni azione simulata serve a verificare se la difesa la vede e come reagisce.\n\nUn **penetration test** classico è più circoscritto di un esercizio red team: cerca di trovare **molte** debolezze in un ambito definito, non di aggirare il monitoraggio.\n\n> Domanda guida: *«Il nostro rilevamento ha visto qualcosa? Quanto ci ha messo il blue team a reagire?»*\n\nIl valore è nel **ciclo di apprendimento**: ogni esercizio produce miglioramenti concreti alle difese e ai tempi di risposta.` },
      { h: 'Ambito, regole di ingaggio e lettera di autorizzazione', b: `Prima di ogni attività si definiscono per iscritto:\n\n- **Ambito** (scope): quali sistemi, reti, applicazioni, sedi e persone sono inclusi, e quali **esclusi**.\n- **Regole di ingaggio** (Rules of Engagement): periodi e orari consentiti, tecniche ammesse o vietate, trattamento dei dati reperiti, limiti sugli effetti sull’operatività.\n- **Contatti di emergenza** e procedura per **fermare** subito il test se qualcosa va storto.\n- **Gestione dei dati**: conservazione sicura e cancellazione dei risultati.\n- **Terze parti**: se un sistema è ospitato da un fornitore o in cloud, servono anche **i permessi del fornitore**; il cliente non può autorizzare ciò che non possiede.\n\nLa **lettera di autorizzazione** (a volte «permission to test» o *get-out-of-jail letter*) firmata da chi ha **l’autorità** sui sistemi indica nominativi, date e ambito, e protegge entrambe le parti.\n\n> Regola semplice: se non è per iscritto e non è nell’ambito, **non si fa**. Se durante il lavoro compare qualcosa di fuori ambito, ci si ferma e si chiede.` },
      { h: 'Fasi metodologiche, a livello concettuale', b: `Esistono metodologie pubbliche che danno struttura e ripetibilità. Le più citate:\n\n- **PTES** (Penetration Testing Execution Standard): preparazione e ingaggio, raccolta di informazioni, modellazione delle minacce, analisi delle vulnerabilità, sfruttamento, post-sfruttamento, **reportistica**.\n- **OWASP WSTG** (Web Security Testing Guide): guida alla verifica della sicurezza delle **applicazioni web**, organizzata per categorie (autenticazione, gestione delle sessioni, validazione dell’input...).\n- **NIST SP 800-115**: guida del NIST alla verifica tecnica di sicurezza, con fasi di **pianificazione**, **scoperta**, **attacco** (verifica) e **reportistica**.\n\nIn sintesi concettuale tutte seguono lo stesso arco:\n\n1. **Pianificare** e ottenere l’autorizzazione.\n2. **Conoscere** il bersaglio autorizzato.\n3. **Individuare** le debolezze.\n4. **Verificare** quelle rilevanti in modo controllato.\n5. **Documentare** e riferire.\n6. **Ripetere la verifica** dopo la correzione.\n\n> Il passaggio più importante, e spesso il più trascurato, è l’ultimo: senza **retest** non sai se il problema è chiuso.` },
      { h: 'Un buon report', b: `Il report è **il prodotto** del test: se non è comprensibile e utile, il lavoro è sprecato. Due livelli di lettura:\n\n- **sintesi per la direzione**: rischio complessivo, risultati principali, priorità, in linguaggio non tecnico;\n- **dettaglio tecnico** per chi deve correggere.\n\nOgni **finding** (risultato) dovrebbe contenere:\n\n- **titolo** chiaro;\n- **descrizione** del problema e dove si trova;\n- **evidenza**: prove riproducibili (schermate, registri, richieste), senza dati sensibili inutili;\n- **impatto** concreto per l’organizzazione;\n- **valutazione del rischio** (per esempio con CVSS e contesto: probabilità e impatto);\n- **rimedio** pratico e verificabile, con priorità;\n- **riferimenti** (CWE, linee guida).\n\n> Cattivo: «XSS presente.» Buono: «Il campo X della pagina Y non filtra l’input, il che permette di eseguire script nel browser degli utenti; impatto: furto di sessioni; rischio: alto; rimedio: codifica dell’output e policy CSP; da verificare con retest.»\n\nSi aggiungono ambito, metodo, limiti (che cosa **non** è stato testato) e punti di forza trovati. Dopo la correzione, il **retest** documenta che i problemi sono davvero chiusi.` },
      { h: 'Bug bounty e divulgazione responsabile', b: `Un **programma di bug bounty** è un invito pubblico o su invito, da parte di un’organizzazione, a segnalare vulnerabilità nei propri sistemi **secondo regole scritte**, spesso con un compenso. Le piattaforme specializzate ospitano molti programmi.\n\nPunti essenziali:\n\n- leggere con cura la **policy**: ambito, sistemi esclusi, azioni vietate, formato della segnalazione, safe harbor (le condizioni alle quali l’organizzazione si impegna a non agire legalmente);\n- **restare nell’ambito** e non accedere a più dati di quanto serva per dimostrare il problema;\n- **non divulgare** pubblicamente prima della correzione;\n- fornire un report chiaro e riproducibile, come descritto sopra.\n\nÈ la **divulgazione coordinata** (*coordinated vulnerability disclosure*): chi trova segnala in modo riservato, il produttore corregge, poi si pubblica in tempi concordati.\n\n> Se un’organizzazione non ha un programma, non significa che i suoi sistemi siano un campo di prova: senza permesso esplicito, **non si testa**. Alcune organizzazioni pubblicano un file di contatto per la sicurezza (security.txt) proprio per ricevere segnalazioni.` },
      { h: 'Dove esercitarsi in modo legale', b: `Per imparare servono ambienti dove **hai il diritto** di provare.\n\n- **Macchine virtuali tue**, su una rete isolata: costruisci un laboratorio con sistemi che possiedi e puoi rompere e ripristinare con uno snapshot.\n- **Applicazioni volutamente vulnerabili** progettate per l’addestramento, da eseguire in locale: per esempio DVWA, OWASP WebGoat e OWASP Juice Shop. Si installano sulla propria macchina o rete di prova, non su Internet aperta.\n- **Piattaforme di sfide e CTF** (Capture The Flag) e laboratori didattici online, come picoCTF, TryHackMe o Hack The Box, dove le sfide sono **create apposta** e le regole sono dichiarate.\n- **Corsi e ambienti di formazione** con laboratori inclusi.\n\nBuone abitudini:\n\n- isola il laboratorio dalla rete di casa o del lavoro;\n- rispetta i **termini d’uso** di ogni piattaforma;\n- tieni appunti e **scrivi report**, come in un incarico vero: è la competenza più richiesta;\n- studia anche il **lato difensivo**: registri, rilevamento, correzione.\n\n> Un buon professionista si riconosce da quanto bene sa **spiegare e correggere**, più che da quanto bene sa colpire.` }
    ],
    exercises: [
      mc('Che cosa distingue un test di penetrazione professionale da un accesso illecito?', ['L’autorizzazione scritta e un ambito concordato', 'La complessità degli strumenti utilizzati nel test', 'Il sistema operativo Linux usato dal tester', 'Il compenso economico ricevuto per il lavoro'], 0, 'L’autorizzazione, con ambito e regole, è la linea di confine.'),
      mc('Il purple team è:', ['Un modo di lavorare in cui red e blue collaborano in modo trasparente', 'Un reparto legale che valuta i contratti stipulati con i clienti e i fornitori', 'Un tipo di firewall applicativo di nuova generazione installato nel perimetro', 'Un gruppo di sviluppo che scrive il codice dei test automatici del prodotto'], 0, 'Serve a verificare se la difesa vede e gestisce le azioni simulate.'),
      mc('Quale elemento fa parte delle regole di ingaggio?', ['Orari consentiti e come fermare subito il test', 'Il prezzo di listino degli strumenti software impiegati nel test', 'L’elenco dei dipendenti da colpire per primi con le simulazioni', 'Il codice sorgente interno dei clienti finali del servizio sotto test'], 0, 'Le regole fissano periodi, limiti, contatti e procedura di arresto.'),
      mc('Un sistema è ospitato da un fornitore cloud. Che cosa serve in più oltre al permesso del cliente?', ['I permessi del fornitore, se richiesti dalle sue regole', 'Nulla: il cliente decide ogni aspetto del test', 'Soltanto un antivirus aggiornato sul PC del tester', 'Il consenso degli altri clienti che usano lo stesso fornitore'], 0, 'Il cliente non può autorizzare ciò che non possiede.'),
      mc('Quale sigla indica una guida per testare la sicurezza delle applicazioni web?', ['OWASP WSTG', 'PTES', 'CIS v8', 'ISO 27002'], 0, 'La Web Security Testing Guide è dedicata alle applicazioni web.'),
      mc('NIST SP 800-115 è:', ['Una guida alla verifica tecnica di sicurezza', 'Una legge europea sulla protezione dei dati', 'Un catalogo di password usate più di frequente', 'Un prodotto commerciale per le scansioni di rete'], 0, 'Descrive pianificazione, scoperta, attacco e reportistica.'),
      mc('Quale parte è essenziale in un finding oltre alla descrizione?', ['Evidenza, impatto e rimedio', 'Solo il nome dell’autore', 'Solo uno schema colorato', 'Il nome del cliente a tutti'], 0, 'Un finding utile ha prove, impatto, rischio e correzione.'),
      mc('Perché si fa un retest?', ['Per verificare che la correzione abbia chiuso il problema', 'Per aumentare il compenso concordato con il cliente', 'Per modificare l’ambito dell’incarico definito all’inizio', 'Per evitare di consegnare il rapporto finale al cliente'], 0, 'Senza retest non c’è prova che il problema sia chiuso.'),
      mc('Quale ambiente è adatto per esercitarsi in modo legale?', ['Un’applicazione vulnerabile eseguita sul proprio laboratorio isolato', 'Il sito di un’azienda scelta a caso su Internet, con test leggeri', 'La rete Wi-Fi domestica di un vicino di casa, di notte e con cautela', 'Il server di un’università, anche senza avere ricevuto il permesso'], 0, 'Si prova solo su sistemi propri o creati apposta per l’addestramento.'),
      mc('Che cosa è la divulgazione coordinata?', ['Segnalare in modo riservato e pubblicare dopo la correzione', 'Pubblicare subito ogni difetto non appena viene scoperto dal ricercatore', 'Vendere le falle scoperte al miglior offerente sul mercato', 'Non comunicare nulla al produttore del software interessato'], 0, 'Il produttore ha il tempo di correggere prima della pubblicazione.'),
      order('Ordina l’arco generale di un incarico autorizzato', ['Autorizzazione', 'Pianificazione', 'Verifica', 'Report', 'Retest'], 'Senza autorizzazione non si comincia; il retest chiude il ciclo.')
    ],
    test: [
      mc('Il red team si differenzia dal blue team perché:', ['Simula un avversario mentre il blue difende', 'Scrive le politiche e le procedure aziendali', 'Si occupa di contabilità e di acquisti', 'Gestisce soltanto l’hardware dei server'], 0, 'Red simula, blue rileva e risponde.'),
      mc('Che cosa dovrebbe fare un tester se trova un sistema fuori ambito?', ['Fermarsi e chiedere', 'Continuare comunque', 'Usarlo per altre prove', 'Pubblicare la scoperta'], 0, 'Fuori ambito significa senza autorizzazione.'),
      mc('La lettera di autorizzazione deve essere firmata da:', ['Chi ha l’autorità sui sistemi', 'Qualsiasi dipendente dell’azienda', 'Il tester che esegue il lavoro', 'Un fornitore non coinvolto nel test'], 0, 'Solo il titolare può autorizzare.'),
      mc('Quale fase di PTES si occupa di comunicare i risultati?', ['Reportistica', 'Preparazione', 'Modellazione delle minacce', 'Post-sfruttamento'], 0, 'L’ultima fase è la reportistica.'),
      mc('Quale piattaforma è nata per sfide didattiche e CTF?', ['picoCTF', 'Un sito qualsiasi senza regole', 'Il sito di una banca', 'Un servizio di posta'], 0, 'Le piattaforme CTF creano sfide apposta e dichiarano regole.'),
      mc('In un programma di bug bounty, una buona segnalazione:', ['Rimane nell’ambito ed è riproducibile e riservata', 'Include tutti i dati personali che sono stati trovati', 'Viene pubblicata subito su un canale aperto', 'Ignora le regole indicate nella policy del programma'], 0, 'Si rispettano ambito, riservatezza e formato richiesti.'),
      mc('Che cosa indica la sezione «limiti» di un report?', ['Ciò che non è stato testato', 'I difetti dei tester incaricati', 'Il budget assegnato al progetto', 'La lista dei sistemi dichiarati sicuri'], 0, 'Dice chiaramente cosa non è coperto dal test.')
    ]
  });

  /* ---------- 5 · Architettura sicura ---------- */
  C.addTopic({
    id: 'cyb-architettura-sicura-e-difesa-in-profondita', subject: 'cyb', stage: 'L5', minutes: 14,
    title: 'Architettura sicura e difesa in profondità',
    summary: 'Principi di progettazione sicura, segmentazione, gestione di segreti e chiavi, resilienza, requisiti e compromessi, con una checklist di revisione del progetto.',
    objectives: ['Applicare i principi di progettazione sicura a un caso concreto', 'Spiegare segmentazione, gestione dei segreti e resilienza', 'Usare una checklist di revisione per valutare un progetto'],
    pages: [
      { h: 'Difesa in profondità', b: `La **difesa in profondità** (*defence in depth*) usa **più livelli di controlli indipendenti**, così che il fallimento di uno non basti a compromettere il sistema.\n\nLivelli tipici:\n\n- **perimetro e rete** (firewall, segmentazione);\n- **host** (aggiornamenti, configurazione sicura, protezione degli endpoint);\n- **applicazione** (validazione dell’input, autenticazione, autorizzazione);\n- **dati** (cifratura, controllo degli accessi, backup);\n- **persone e processi** (formazione, procedure, monitoraggio);\n- **fisico** (accessi ai locali).\n\n> Un castello ha fossato, mura, torri e guardie: nessuno dei livelli è perfetto, ma insieme obbligano l’avversario a superarne molti, e danno il tempo di **accorgersene**.\n\nDue precisazioni. I livelli devono essere **diversi** nel funzionamento: due controlli identici che condividono lo stesso difetto si rompono insieme. E la profondità comprende **rilevamento e risposta**, non solo prevenzione: si suppone che, prima o poi, qualcosa passerà.\n\nQuesto atteggiamento si chiama *assume breach*: progetta come se un livello fosse già stato superato.` },
      { h: 'I principi di progettazione', b: `Dagli studi classici sulla sicurezza dei sistemi derivano principi ancora validi.\n\n- **Minimo privilegio**: ogni utente, processo e servizio ha **solo** i permessi necessari al proprio compito.\n- **Separazione dei compiti**: operazioni critiche richiedono **più persone** o ruoli, così che una sola non possa abusarne o sbagliare senza controllo.\n- **Fail-secure** (*fail-safe defaults*): in caso di guasto o dubbio, il sistema **nega** l’accesso invece di concederlo.\n- **Sicuro per impostazione predefinita** (*secure defaults*): la configurazione iniziale è già prudente; abbassare la protezione richiede una scelta esplicita.\n- **Ridurre la superficie d’attacco**: meno funzioni, porte, servizi e componenti attivi, meno punti da difendere.\n- **Economia dei meccanismi**: progetti **semplici** e piccoli sono più facili da verificare e hanno meno errori.\n- **Mediazione completa**: ogni accesso è controllato, ogni volta.\n- **Progettazione aperta**: la sicurezza non dipende dalla segretezza del progetto, ma da quella delle **chiavi**.\n\n> Un esempio di fail-secure: se il servizio di autorizzazione non risponde, la richiesta viene rifiutata, non accettata «per non bloccare».` },
      { h: 'Architetture di riferimento e segmentazione', b: `Un’**architettura di riferimento** è un modello consolidato da adattare, che evita di reinventare soluzioni. Esempi: le linee guida dei fornitori cloud, il modello a livelli (presentazione, applicazione, dati), le raccomandazioni di framework come NIST o CIS.\n\nLa **segmentazione** divide la rete in **zone** con regole fra loro, per limitare i danni e il movimento laterale.\n\n- Zone tipiche: utenti, server applicativi, database, gestione/amministrazione, ospiti, dispositivi IoT.\n- Il traffico tra zone passa da **punti di controllo** (firewall, gruppi di sicurezza) con regole del tipo «**nega tutto, consenti il necessario**».\n- La **DMZ** ospita i servizi esposti, separati dalla rete interna.\n- La **microsegmentazione** applica il principio fino ai singoli carichi di lavoro.\n\n> Se un portatile viene compromesso, la segmentazione impedisce che da lì si raggiunga direttamente il database dei clienti.\n\nIl modello **zero trust** va nella stessa direzione: nessuna fiducia implicita basata solo sulla posizione in rete; ogni richiesta è **verificata** (identità, stato del dispositivo, contesto) e autorizzata con il minimo privilegio.` },
      { h: 'Segreti e gestione delle chiavi', b: `**Segreti** sono password, chiavi API, certificati, token e chiavi di cifratura. Sono tra gli asset più delicati.\n\nBuone pratiche:\n\n- **mai nel codice** né nei repository, nelle immagini o nei file di configurazione in chiaro;\n- conservarli in un **gestore di segreti** o in un **modulo di sicurezza** (come un HSM o un servizio di gestione chiavi), con controllo degli accessi e registro delle letture;\n- **minimo privilegio**: ogni servizio accede solo ai propri segreti;\n- **rotazione** periodica e rotazione immediata in caso di sospetta esposizione;\n- **credenziali di breve durata** dove possibile, al posto di segreti permanenti;\n- **separare** le chiavi dai dati che proteggono: se stanno nello stesso posto, la cifratura serve a poco;\n- **ciclo di vita**: generazione, distribuzione, uso, rotazione, revoca, distruzione;\n- **backup sicuro** delle chiavi: perdere la chiave significa perdere i dati cifrati.\n\n> Un segreto finito per errore in un repository pubblico va considerato **compromesso**: si revoca e si sostituisce, anche se lo si cancella dalla cronologia.` },
      { h: 'Resilienza', b: `La **resilienza** è la capacità di **continuare a funzionare, degradare con grazia e riprendersi** dopo un guasto o un attacco.\n\nStrumenti architetturali:\n\n- **ridondanza**: più istanze, percorsi di rete o siti, per eliminare i punti singoli di guasto (SPOF);\n- **distribuzione** su più zone di disponibilità;\n- **backup** verificati, con copie **isolate e immutabili** contro cancellazione e cifratura malevola;\n- **limitazione delle richieste** e protezione dal sovraccarico;\n- **degrado controllato**: se un componente secondario cade, il servizio essenziale resta;\n- **isolamento dei guasti**: un problema non si propaga ai componenti vicini;\n- **monitoraggio e allarmi**, con procedure di recupero collaudate;\n- **automazione** della ricostruzione (infrastruttura come codice) per riprendersi in fretta.\n\n> Una **regola di backup nota**, 3-2-1: **3** copie dei dati, su **2** tipi di supporto diversi, con **1** copia fuori sede (o isolata).\n\nE soprattutto **si prova**: un backup mai ripristinato è una speranza, non una garanzia. I tempi di recupero si misurano con RTO e RPO (vedi la lezione sulla continuità).` },
      { h: 'Requisiti e compromessi', b: `La sicurezza si progetta partendo da **requisiti**, non da un elenco di prodotti. Si ricavano da: valutazione del rischio, obblighi normativi e contrattuali, valore dei dati e degli obiettivi di business.\n\nUn requisito ben scritto è **verificabile**:\n\n> Debole: «Il sistema deve essere sicuro.» Buono: «Le sessioni scadono dopo 15 minuti di inattività; l’accesso amministrativo richiede autenticazione a più fattori.»\n\nOgni scelta comporta **compromessi**:\n\n- **sicurezza e usabilità**: controlli troppo pesanti spingono le persone ad aggirarli;\n- **sicurezza e prestazioni**: cifratura, ispezione e controlli hanno un costo;\n- **sicurezza e costo**: ridondanza e monitoraggio richiedono risorse;\n- **disponibilità e riservatezza** possono entrare in conflitto (per esempio, chiudere un sistema compromesso interrompe il servizio).\n\nLa decisione si fa guardando il **rischio** (vedi la lezione quantitativa): una misura sproporzionata rispetto al rischio non è «più sicura», è solo più costosa.\n\nSi documentano le scelte e le **accettazioni di rischio**, con responsabili e riesami.` },
      { h: 'Checklist di revisione del progetto', b: `La **revisione della progettazione** (*design review*) controlla un’architettura **prima** della realizzazione, quando correggere costa poco. Una checklist di base:\n\n1. **Asset e dati**: quali sono, dove si trovano, quanto sono sensibili? Cosa succede se vengono persi o divulgati?\n2. **Confini di fiducia**: dove i dati passano tra zone o componenti con livelli di fiducia diversi? Ogni passaggio è controllato?\n3. **Identità e accessi**: autenticazione forte, autorizzazione, minimo privilegio, separazione dei compiti per le azioni critiche.\n4. **Segmentazione**: zone, regole «nega per default», accesso amministrativo separato.\n5. **Protezione dei dati**: cifratura in transito e a riposo, gestione di chiavi e segreti.\n6. **Configurazione**: valori predefiniti sicuri, componenti inutili rimossi.\n7. **Registrazione e rilevamento**: eventi importanti registrati, conservati, monitorati; orologi sincronizzati.\n8. **Resilienza**: SPOF, backup isolati e provati, RTO e RPO coerenti.\n9. **Guasti**: cosa succede se un componente non risponde? Comportamento *fail-secure*?\n10. **Terze parti e dipendenze**: aggiornamenti, fornitori, supply chain.\n11. **Verifica e ripristino**: test, aggiornamenti, risposta agli incidenti.\n\n> Ogni «non lo so» nella checklist è un **rischio da chiarire**, non un punto da saltare.` }
    ],
    exercises: [
      mc('Che cosa significa difesa in profondità?', ['Più livelli di controlli indipendenti', 'Un unico firewall molto potente', 'La segretezza assoluta del progetto', 'Un aggiornamento completo una volta all’anno'], 0, 'Il fallimento di un livello non deve bastare a compromettere il sistema.'),
      mc('Il principio del minimo privilegio dice che:', ['Ognuno ha solo i permessi necessari al proprio compito', 'Gli amministratori mantengono sempre ogni permesso del sistema', 'I permessi già assegnati a un utente non si revocano più', 'Tutti i colleghi di un reparto condividono un unico account'], 0, 'I permessi minimi riducono i danni da errore o abuso.'),
      mc('Che cos’è un comportamento fail-secure?', ['In caso di guasto il sistema nega l’accesso', 'In caso di guasto concede l’accesso per non bloccare', 'Il sistema si spegne sempre', 'Il sistema ignora gli errori'], 0, 'In dubbio si nega, non si concede.'),
      mc('La separazione dei compiti serve a:', ['Evitare che una sola persona possa abusare di operazioni critiche senza controllo', 'Far lavorare meno persone possibili sullo stesso processo aziendale', 'Ridurre il numero di backup che occorre conservare nel tempo', 'Sostituire la cifratura nella protezione dei dati più sensibili'], 0, 'Più ruoli per le azioni critiche riducono frodi ed errori.'),
      mc('Ridurre la superficie d’attacco significa:', ['Disattivare funzioni e servizi non necessari', 'Aggiungere altre porte aperte per facilitare i test', 'Usare password uguali su più sistemi aziendali', 'Nascondere i dettagli del progetto ai fornitori'], 0, 'Meno componenti attivi, meno punti da difendere.'),
      mc('Qual è l’obiettivo della segmentazione di rete?', ['Limitare i danni e il movimento laterale', 'Aumentare la velocità di ogni singola rete', 'Eliminare i firewall interni dell’azienda', 'Evitare di dover usare le password'], 0, 'Zone separate con regole tra loro contengono la compromissione.'),
      mc('Dove NON vanno conservati i segreti?', ['Nel codice sorgente e nei repository', 'In un gestore di segreti con controllo accessi', 'In un servizio di gestione chiavi', 'In un HSM'], 0, 'Un segreto nel repository va considerato compromesso.'),
      mc('Nella regola di backup 3-2-1 il «1» indica:', ['Una copia fuori sede o isolata', 'Un solo supporto di memorizzazione', 'Un solo backup eseguito al giorno', 'Un solo amministratore autorizzato'], 0, '3 copie, 2 tipi di supporto, 1 copia fuori sede o isolata.'),
      fill('Quante copie dei dati prevede la regola 3-2-1?', ['3', 'tre'], 'Tre copie dei dati.'),
      mc('Quale requisito è scritto in modo verificabile?', ['Le sessioni scadono dopo 15 minuti di inattività', 'Il sistema deve essere sicuro per tutti gli utenti', 'Si userà una protezione sufficientemente buona', 'Gli utenti dovranno essere sempre molto attenti'], 0, 'Un requisito misurabile si può testare.'),
      order('Ordina l’approccio alla progettazione sicura', ['Requisiti', 'Rischi', 'Progetto', 'Revisione', 'Realizzazione'], 'Si parte dai requisiti e dai rischi, si progetta e si rivede prima di costruire.')
    ],
    test: [
      mc('Perché due controlli identici non garantiscono difesa in profondità?', ['Perché condividono lo stesso difetto e possono cedere insieme', 'Perché due controlli uguali costano troppo all’azienda e non servono', 'Perché la normativa di settore vieta di duplicare i controlli', 'Perché due controlli uguali rallentano troppo il sistema produttivo'], 0, 'I livelli devono essere diversi e indipendenti.'),
      mc('Quale principio sostiene che la sicurezza non dipenda dalla segretezza del progetto?', ['Progettazione aperta', 'Fail-secure', 'Mediazione completa', 'Separazione dei compiti'], 0, 'Dipende dalla segretezza delle chiavi, non dell’algoritmo o del progetto.'),
      mc('Che cosa significa zero trust?', ['Nessuna fiducia implicita: ogni richiesta è verificata', 'Nessun controllo sui dispositivi personali dei dipendenti', 'Fiducia basata sulla sede fisica da cui si collega l’utente', 'Nessuna autenticazione richiesta per gli utenti della rete interna'], 0, 'Si verificano identità, dispositivo e contesto a ogni richiesta.'),
      mc('Che cosa è un SPOF?', ['Un punto singolo di guasto', 'Un tipo di algoritmo di cifratura', 'Un gruppo di utenti privilegiati', 'Un firewall di nuova generazione'], 0, 'La ridondanza serve a eliminarlo.'),
      mc('Perché un backup deve essere ripristinato in prova?', ['Perché un backup mai provato non garantisce il recupero', 'Per consumare lo spazio di archiviazione rimasto libero', 'Perché lo richiede il protocollo di rete usato per copiare', 'Perché a ogni prova di ripristino viene cambiata la chiave'], 0, 'Solo il test dimostra che il ripristino funziona.'),
      mc('Quale conflitto tipico si ha tra sicurezza e usabilità?', ['Controlli troppo pesanti spingono ad aggirarli', 'La cifratura rende visibili i dati agli utenti', 'Gli utenti smettono di esistere nel sistema', 'Il costo dei controlli cala sempre con l’uso'], 0, 'Un controllo non usabile viene spesso aggirato.'),
      mc('In una design review, «Cosa succede se il servizio di autorizzazione non risponde?» verifica:', ['Il comportamento fail-secure', 'Il costo delle licenze del servizio', 'La quantità di log prodotti ogni giorno', 'Il numero massimo di utenti connessi'], 0, 'Si controlla che in caso di guasto si neghi l’accesso.')
    ]
  });

  /* ---------- 6 · Continuità operativa e crisi ---------- */
  C.addTopic({
    id: 'cyb-continuita-operativa-e-crisi', subject: 'cyb', stage: 'L5', minutes: 14,
    title: 'Continuità operativa, crisi e cultura della sicurezza',
    summary: 'BCP e DR, BIA, RTO, RPO e MTD con calcoli, comunicazione di crisi, esercitazioni, rischio di terze parti, metriche per il management e percorsi professionali.',
    objectives: ['Distinguere BCP e DR e usare BIA, RTO, RPO e MTD con numeri', 'Pianificare comunicazione di crisi ed esercitazioni, e valutare il rischio dei fornitori', 'Scegliere metriche per il management e conoscere i percorsi professionali'],
    pages: [
      { h: 'BCP e DR', b: `Gli incidenti gravi capitano: la domanda è **come si continua** e **come si riparte**.\n\n- **Business Continuity Plan (BCP)**: piano per mantenere **le funzioni essenziali** dell’organizzazione durante e dopo un’interruzione (non solo IT: persone, sedi, fornitori, comunicazione).\n- **Disaster Recovery (DR)**: la parte che riguarda il **ripristino dei sistemi informatici e dei dati**.\n\nIl DR è dunque un sottoinsieme del BCP.\n\n> Se un ufficio è inagibile, il BCP stabilisce dove e come lavorano le persone; il DR stabilisce come tornano disponibili le applicazioni.\n\nUn buon piano contiene: **ruoli e responsabilità**, elenco dei **contatti**, **priorità** dei servizi, procedure di attivazione, risorse alternative, comunicazione, criteri per tornare alla normalità.\n\nIl piano deve essere **accessibile durante la crisi**, anche se i sistemi principali sono fuori uso: una copia stampata o in un luogo indipendente fa la differenza. E va **aggiornato** a ogni cambiamento importante.\n\nLo standard di riferimento per i sistemi di gestione della continuità è ISO 22301.` },
      { h: 'BIA: che cosa conta davvero', b: `La **Business Impact Analysis (BIA)** è l’analisi che stabilisce **quali processi sono critici** e **quanto costa la loro interruzione**.\n\nPassi:\n\n1. elencare i **processi** dell’organizzazione;\n2. per ciascuno, stimare l’**impatto nel tempo** (perdite economiche, penali, obblighi di legge, reputazione, effetti sulle persone);\n3. identificare le **dipendenze** (sistemi, persone, fornitori, sedi);\n4. fissare **tempi massimi accettabili** e priorità di ripristino.\n\n> Esempio: il sistema di ordini online fa perdere 12 000 € ogni ora di fermo; il portale interno delle ferie quasi nulla. Il primo ha priorità di ripristino molto più alta.\n\nL’impatto di solito **cresce** con la durata dell’interruzione: dopo qualche ora si perdono vendite; dopo qualche giorno, clienti e contratti.\n\nLa BIA evita due errori: proteggere **tutto** allo stesso modo (costoso e impraticabile) o proteggere **ciò che si vede** invece di ciò che conta. È il collegamento diretto con il rischio e con la scelta degli investimenti.` },
      { h: 'RTO, RPO e MTD con numeri', b: `Tre parametri che si decidono con la BIA.\n\n- **RTO** (Recovery Time Objective): **tempo massimo** entro cui il servizio deve essere ripristinato.\n- **RPO** (Recovery Point Objective): **quantità massima di dati** che si accetta di perdere, espressa come tempo (quanto indietro nel tempo si può tornare).\n- **MTD** (Maximum Tolerable Downtime): **durata massima di interruzione** che l’organizzazione può sopportare prima di danni inaccettabili.\n\nRelazione: **MTD = RTO + WRT**, dove WRT (Work Recovery Time) è il tempo per verificare e riprendere il lavoro dopo il ripristino tecnico.\n\n**Esempio 1.** MTD 8 ore, RTO 5 ore → WRT massimo = 8 − 5 = **3 ore**.\n\n**Esempio 2.** RPO 1 ora, ma i backup si eseguono ogni 6 ore: nel caso peggiore si perdono **6 ore** di dati, più dell’RPO. Per rispettarlo serve un backup (o una replica) almeno **ogni ora**.\n\n**Esempio 3.** Fermo di 5 ore con perdita di 12 000 € l’ora: costo = 5 × 12 000 = **60 000 €**.\n\n> Più l’RTO e l’RPO sono bassi, più la soluzione costa (replica continua, siti attivi in parallelo): si sceglie in base alla BIA.` },
      { h: 'Disponibilità in numeri', b: `Gli accordi di servizio esprimono la disponibilità in **percentuale**. Piccole differenze valgono molto.\n\n> Un anno ha 365 × 24 = **8 760 ore**.\n\n- **99%** → fermo ammesso 1% × 8 760 = **87,6 ore** all’anno.\n- **99,9%** → 0,1% × 8 760 = **8,76 ore** all’anno.\n- **99,99%** → 0,01% × 8 760 = **0,876 ore** = circa **52,6 minuti** all’anno.\n\nPer un mese di 30 giorni (720 ore): al 99,9% sono 0,72 ore = **43,2 minuti**.\n\nQuesto aiuta a tradurre un requisito in decisioni: passare da 99,9% a 99,99% significa ridurre il fermo annuo di circa **8 ore** (da 8,76 a circa 0,88), ma di solito richiede ridondanza, replica e monitoraggio molto più costosi.\n\n> La domanda giusta non è «quanti nove?», ma: **«quanto costa un’ora di fermo e quanto costa evitarla?»**\n\nAttenzione anche ai **tempi esclusi** dal calcolo (manutenzioni programmate, cause esterne) e a come il fornitore misura la disponibilità.` },
      { h: 'Gestione della crisi e comunicazione', b: `In una crisi si decide in fretta e con informazioni incomplete: la preparazione evita il caos.\n\n**Struttura**\n- un **responsabile della crisi** con autorità di decisione;\n- un **team** con ruoli chiari (tecnico, legale, comunicazione, risorse umane, direzione);\n- un **registro delle decisioni** con orari;\n- canali di comunicazione **alternativi** se quelli abituali sono compromessi.\n\n**Comunicazione**\n- **tempestiva, veritiera e coerente**: una sola fonte autorevole;\n- destinatari diversi (dipendenti, clienti, autorità, fornitori, stampa) con messaggi adatti;\n- niente supposizioni né colpe: dire **che cosa si sa, che cosa non si sa ancora, che cosa si sta facendo** e quando ci sarà un aggiornamento;\n- coordinarsi con la parte **legale** per gli obblighi di notifica (per esempio le violazioni di dati personali, vedi la lezione sulla conformità).\n\n> Una comunicazione tardiva o contraddittoria danneggia la fiducia più dell’incidente stesso.\n\nDopo la crisi, una **revisione post-incidente** senza ricerca di colpevoli (*blameless*) raccoglie cause, decisioni e miglioramenti.` },
      { h: 'Esercitazioni e rischio di terze parti', b: `Un piano mai provato è un’ipotesi. Si distinguono:\n\n- **Verifica documentale**: rilettura del piano per trovare lacune.\n- **Tabletop exercise**: la squadra discute a tavolino uno **scenario** (per esempio un attacco ransomware nel fine settimana) e dice che cosa farebbe. Poco costoso e molto istruttivo: emergono ruoli poco chiari, contatti mancanti, decisioni non assegnate.\n- **Prova tecnica**: ripristino reale di sistemi e dati in un ambiente di prova.\n- **Esercitazione completa**: simulazione di interruzione con coinvolgimento di tutti.\n\nOgni esercizio produce **azioni correttive** con responsabili e scadenze.\n\n**Terze parti e supply chain.** Fornitori, servizi cloud e componenti software sono anche **la tua superficie di rischio**.\n\n- **Classificare** i fornitori per criticità e accesso ai dati.\n- **Valutarli**: questionari, evidenze (certificazioni, rapporti come SOC 2), clausole contrattuali su sicurezza, notifica degli incidenti, diritto di audit.\n- **Monitorare** nel tempo, non solo alla firma.\n- Conoscere le **dipendenze** del software (inventario dei componenti, per esempio in forma di SBOM) e prevedere un **piano di uscita**.\n\n> Un fornitore critico senza alternativa è un SPOF organizzativo.` },
      { h: 'Metriche, report e cultura, e un’ultima pagina sulla carriera', b: `**Metriche per il management.** Poche, chiare, collegate al rischio:\n\n- **MTTD** (tempo medio di rilevamento) e **MTTR** (tempo medio di risposta o ripristino);\n- percentuale di **patch applicate entro SLA** (ad esempio 180 su 200 = 90%);\n- tasso di **click** nelle simulazioni di phishing e di **segnalazioni** degli utenti;\n- copertura dell’**autenticazione a più fattori** e dei backup **testati**;\n- numero di **rischi aperti** oltre scadenza.\n\nLe metriche vanno riferite a **decisioni**, non esibite per decorazione.\n\n**Cultura della sicurezza.** Dipende dalla direzione che dà l’esempio, da regole realistiche, da una **segnalazione senza paura** degli errori e da formazione utile e breve. Le persone sono parte della difesa.\n\n**Carriere, senza enfasi.** Ci sono ruoli di analista SOC, amministratore di sistemi sicuri, sviluppatore sicuro, consulente di rischio e conformità, risposta agli incidenti, tester autorizzato. Le **certificazioni** (per esempio Security+, CISSP, CISM, CEH, OSCP, ISO 27001 Lead Auditor) possono aiutare a strutturare lo studio e a farsi riconoscere, ma **non sostituiscono la pratica**. Il lavoro è spesso fatto di documentazione, procedure e comunicazione, più che di scene da film. Si costruisce con basi solide, curiosità, laboratori e portfolio.` }
    ],
    exercises: [
      mc('Qual è il rapporto tra BCP e DR?', ['Il DR è la parte del BCP dedicata al ripristino di sistemi e dati', 'BCP e DR sono due sigle diverse che indicano il medesimo piano', 'Il BCP riguarda soltanto i servizi ospitati presso un fornitore cloud', 'Il DR riguarda soltanto le persone e la loro formazione periodica'], 0, 'Il BCP è più ampio; il DR è il sottoinsieme informatico.'),
      mc('Che cosa stabilisce la BIA?', ['Quali processi sono critici e quanto costa interromperli', 'Quali password vanno cambiate dopo un incidente di sicurezza', 'Quale budget dedicare alle attività di comunicazione esterna', 'Quali turni garantiscono la presenza del personale in sede'], 0, 'Misura l’impatto dell’interruzione e fissa le priorità.'),
      mc('Che cosa esprime l’RPO?', ['Quanti dati si accetta di perdere, in termini di tempo', 'Il tempo massimo previsto per il ripristino del servizio', 'Il costo economico complessivo stimato di un incidente', 'Il numero minimo di copie di backup da conservare'], 0, 'L’RPO è il punto nel tempo a cui si può tornare.'),
      fill('MTD 8 ore e RTO 5 ore: quante ore al massimo di WRT?', ['3', 'tre'], 'MTD = RTO + WRT, quindi WRT = 8 − 5 = 3.'),
      mc('RPO 1 ora, backup ogni 6 ore. Che cosa succede nel caso peggiore?', ['Si perdono fino a 6 ore di dati: l’RPO non è rispettato', 'Si perde al massimo 1 ora di dati: l’RPO viene rispettato', 'Non si perde alcun dato perché il backup periodico lo evita', 'Si perdono fino a 7 ore di dati: 6 di intervallo più 1 di RPO'], 0, 'Il backup deve essere almeno ogni ora per rispettare l’RPO.'),
      fill('Un fermo di 5 ore costa 12 000 € l’ora. Quanto costa in totale in euro?', ['60000', '60 000', '60.000'], '5 × 12 000 = 60 000.'),
      fill('Quante ore ha un anno non bisestile (365 giorni)?', ['8760', '8 760', '8.760'], '365 × 24 = 8 760.'),
      fill('Quante ore di fermo annuo ammette una disponibilità del 99,9%?', ['8,76', '8.76'], '0,1% di 8 760 = 8,76 ore.'),
      mc('99,99% di disponibilità in un anno corrisponde a circa:', ['52,6 minuti di fermo', '8,76 ore di fermo in un anno', '87,6 ore di fermo in un anno', '5 minuti di fermo in un anno'], 0, '0,01% di 8 760 = 0,876 ore, circa 52,6 minuti.'),
      mc('Qual è il vantaggio principale di un tabletop exercise?', ['Far emergere ruoli e decisioni poco chiari a basso costo', 'Sostituire ogni prova tecnica di ripristino dei sistemi critici', 'Rendere superfluo il piano scritto di continuità operativa', 'Misurare le prestazioni dei dischi dei server di backup'], 0, 'Si discute uno scenario e si scoprono le lacune del piano.'),
      order('Ordina il ciclo di preparazione alla continuità', ['BIA', 'Obiettivi RTO e RPO', 'Piano', 'Esercitazione', 'Azioni correttive'], 'Dall’analisi degli impatti alla prova e ai miglioramenti.')
    ],
    test: [
      mc('Che cosa significa MTD?', ['Durata massima di interruzione tollerabile', 'Quantità massima di dati ripristinabili dal backup', 'Misura tecnica di difesa applicata al perimetro', 'Tempo medio impiegato per diagnosticare un guasto'], 0, 'Maximum Tolerable Downtime.'),
      fill('Con MTD 10 ore e WRT 4 ore, quante ore al massimo per l’RTO?', ['6', 'sei'], 'RTO = MTD − WRT = 10 − 4 = 6.'),
      fill('Un fermo di 3 ore a 8 000 € l’ora costa in euro:', ['24000', '24 000', '24.000'], '3 × 8 000 = 24 000.'),
      mc('Per un mese di 30 giorni, il 99,9% di disponibilità ammette:', ['43,2 minuti di fermo', '7,2 ore di fermo in un mese', '4,32 minuti di fermo al mese', '72 minuti di fermo al mese'], 0, '720 ore × 0,1% = 0,72 ore = 43,2 minuti.'),
      mc('Perché un fornitore critico va monitorato nel tempo?', ['Perché il suo rischio cambia dopo la firma del contratto', 'Perché dopo la firma il contratto non ha più effetto', 'Perché cambiano nel tempo il nome e la sede legale', 'Perché il monitoraggio sostituisce le sue certificazioni'], 0, 'Valutare solo alla firma non basta.'),
      mc('Una buona comunicazione di crisi:', ['Dice che cosa si sa, che cosa no e quando ci sarà un aggiornamento', 'Minimizza l’accaduto finché non sono noti tutti i dettagli tecnici', 'Indica subito il responsabile interno dell’errore che l’ha causato', 'Usa un messaggio diverso per ciascuno dei gruppi di destinatari'], 0, 'Deve essere tempestiva, veritiera e coerente.'),
      mc('Quale affermazione sulle certificazioni professionali è realistica?', ['Aiutano a strutturare lo studio ma non sostituiscono la pratica', 'Garantiscono un posto di lavoro a chiunque le ottenga presto', 'Sono obbligatorie per ricoprire qualunque ruolo nella sicurezza', 'Rendono superflua l’esperienza maturata direttamente sul campo'], 0, 'Sono un supporto, non una scorciatoia.')
    ]
  });
})(window.ST = window.ST || {});
